static int
ocp_byte_w0w1(struct r8152 *tp, u16 type, u16 index, u8 clear, u8 set)
{
	u32 ocp_data;
	int ret;

	ret = ocp_read_byte(tp, type, index, &ocp_data);
	if (ret < 0)
		goto out;

	ocp_data = (ocp_data & ~clear) | set;
	ret = ocp_write_byte(tp, type, index, ocp_data);

out:
	return ret;
}
